/**
 * Serial adaptive polling shared by timers and UI events.
 *
 * start({ immediate = true }) activates the scheduler. request() runs now when
 * idle, or queues at most one follow-up while a run is in flight. Feed-back
 * events generated by run itself should use request({ queue: false }): they
 * are ignored while running rather than creating a perpetual immediate loop.
 * stop() drops timers and queued work. It cannot abort run's own network work;
 * a restart waits for that old run before starting another, so runs never overlap.
 * delay({ failures, lastError }) is evaluated after completion, in milliseconds.
 */
export function createPolling({ run, delay = () => 30000, timers = globalThis, onError } = {}) {
  if (typeof run !== 'function') throw new TypeError('Polling requires an asynchronous run function.');
  if (!timers || typeof timers.setTimeout !== 'function' || typeof timers.clearTimeout !== 'function') throw new TypeError('Polling timers must provide setTimeout and clearTimeout.');
  let active = false, running = false, queued = false, timer = null;
  let epoch = 0, timerToken = 0, failures = 0, lastError = null, lastDelay = null;

  function getState() {
    return { running, queued, stopped: !active, active, timerScheduled: timer !== null, failures, lastError, lastDelay };
  }
  function report(error) {
    if (typeof onError === 'function') {
      try { onError(error, getState()); } catch { /* A reporting callback cannot break serialization. */ }
    }
  }
  function clearTimer() {
    timerToken++;
    if (timer !== null) { timers.clearTimeout(timer); timer = null; }
  }
  function schedule() {
    if (!active || running) return;
    clearTimer();
    let value;
    try { value = typeof delay === 'function' ? delay({ failures, lastError }) : delay; }
    catch (error) { report(error); value = 30000; }
    if (!active || running) return;
    lastDelay = typeof value === 'number' && Number.isFinite(value) ? Math.max(100, Math.min(120000, Math.floor(value))) : 30000;
    const token = timerToken, scheduledEpoch = epoch;
    try {
      timer = timers.setTimeout(() => {
        if (!active || token !== timerToken || scheduledEpoch !== epoch) return;
        timer = null;
        void execute();
      }, lastDelay);
    } catch (error) { active = false; queued = false; timer = null; report(error); }
  }
  async function execute() {
    if (!active || running) return;
    clearTimer(); running = true;
    const runEpoch = epoch;
    try {
      await run();
      if (active && runEpoch === epoch) { failures = 0; lastError = null; }
    } catch (error) {
      if (active && runEpoch === epoch) { failures++; lastError = error; report(error); }
    } finally {
      running = false;
      if (!active) return;
      if (queued) { queued = false; void execute(); }
      else schedule();
    }
  }
  function start({ immediate = true } = {}) {
    if (active) return false;
    active = true; epoch++; failures = 0; lastError = null;
    if (running) { queued = Boolean(immediate); return true; }
    if (immediate) void execute(); else schedule();
    return true;
  }
  function request({ queue = true } = {}) {
    if (!active) return false;
    if (running) {
      if (!queue || queued) return false;
      queued = true; return true;
    }
    clearTimer(); void execute(); return true;
  }
  function stop() {
    active = false; epoch++; queued = false; clearTimer();
  }
  return Object.freeze({ start, request, stop, getState });
}
